<?php if(in_array($record['status'],['refunded','rejected'],true)): ?><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="status"><input type="hidden" name="return_id" value="<?= (int)$record['id'] ?>"><input type="hidden" name="status" value="closed"><button class="btn secondary">İade kaydını kapat</button></form><?php endif; ?>
